parameters.content:
### Workflow: Daily Staff Briefing for {{CLINIC_NAME}}

**Goal:** To prepare the entire team for the day's appointments.

**How it works:**
1. **Trigger:** Runs automatically every morning at {{BRIEFING_TIME}}
2. **Get Today's Calendar Appointments:** Fetches all appointments for the current day from Google Calendar
3. **Format Briefing:** Processes appointment data and formats into a briefing message
4. **Send Briefing:** Sends the formatted briefing to the designated staff communication channel

**Customizable Settings:**
- Clinic Name: {{CLINIC_NAME}}
- Briefing Time: {{BRIEFING_TIME}}
- Timezone: {{TIMEZONE}}
- Communication Channel: {{SLACK_CHANNEL_NAME}}

parameters.text:
=🏥 **{{CLINIC_NAME}} - Daily Staff Briefing**
📅 Date: {{ $now.setZone('{{TIMEZONE}}').toFormat('EEEE, MMMM d, yyyy') }}

{{ $json.briefingMessage }}

parameters.jsCode:
const events = $input.all().map((item) => item.json);

let briefingMessage = "";

if (events.length === 0) {
  briefingMessage = "✅ **No appointments scheduled for today.**\n\n🎉 Great day to catch up on administrative tasks, deep cleaning, or staff training!";
} else {
  const appointmentCount = events.length;
  briefingMessage = `📋 **${appointmentCount} appointment${appointmentCount > 1 ? 's' : ''} scheduled for today:**\n\n`;

  briefingMessage += events
    .sort((a, b) => new Date(a.start?.dateTime || a.start?.date) - new Date(b.start?.dateTime || b.start?.date))
    .map((event, index) => {
      const startTime = event.start?.dateTime || event.start?.date;
      const endTime = event.end?.dateTime || event.end?.date;
      const summary = event.summary || 'Appointment';

      let timeDisplay = '';
      if (startTime.includes('T')) {
        // Time-based event
        const start = new Date(startTime).toLocaleTimeString('en-US', { 
          hour: 'numeric', 
          minute: '2-digit', 
          hour12: true,
          timeZone: '{{TIMEZONE}}'
        });
        const end = new Date(endTime).toLocaleTimeString('en-US', { 
          hour: 'numeric', 
          minute: '2-digit', 
          hour12: true,
          timeZone: '{{TIMEZONE}}'
        });
        timeDisplay = `${start} - ${end}`;
      } else {
        // All-day event
        timeDisplay = 'All Day';
      }

      let petInfo = '';
      if (event.description) {
        const petIdMatch = event.description.match(/Pet ID: (\d+)/);
        const petNameMatch = event.description.match(/Pet Name: ([^\n]+)/);
        const ownerMatch = event.description.match(/Owner: ([^\n]+)/);

        if (petIdMatch || petNameMatch || ownerMatch) {
          petInfo = ' - ';
          if (petNameMatch) petInfo += `🐾 ${petNameMatch[1]}`;
          if (ownerMatch) petInfo += ` (Owner: ${ownerMatch[1]})`;
          if (petIdMatch) petInfo += ` [ID: ${petIdMatch[1]}]`;
        }
      }

      return `${index + 1}. **${timeDisplay}** - ${summary}${petInfo}`;
    })
    .join('\n');

  briefingMessage += `\n\n💡 **Remember:**\n• Check appointment notes for special requirements\n• Ensure all necessary supplies are ready\n• Review patient history before appointments`;
}

return { briefingMessage };
